'use strict';

// MODULES //

var constantFunction = require( '@stdlib/utils/constant-function' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var ln = require( '@stdlib/math/base/special/ln' );
var erf = require( '@stdlib/math/base/special/erf' );
var NINF = require( '@stdlib/constants/float64/ninf' );
var SQRT2 = require( '@stdlib/constants/float64/sqrt-two' );


// VARIABLES //

var INV_SQRT_TWO = 1.0 / SQRT2;


// MAIN //

/**
* Returns a function for evaluating the natural logarithm of the cumulative distribution function (CDF) for a half-normal distribution.
*
* @param {PositiveNumber} sigma - scale parameter
* @returns {Function} logcdf
*
* @example
* var logcdf = factory( 2.0 );
* var y = logcdf( 1.0 );
* // returns ~-0.960
*
* y = logcdf( -1.0 );
* // returns -Infinity
*/
function factory( sigma ) {
	if (
		isnan( sigma ) ||
		sigma <= 0.0
	) {
		return constantFunction( NaN );
	}

	return logcdf;

	/**
	* Evaluate the natural logarithm of the cumulative distribution function (CDF) for a half-normal distribution.
	*
	* @private
	* @param {number} x - input value
	* @returns {number} evaluated logcdf
	*/
	function logcdf( x ) {
		var z;
		if ( x < 0.0 ) {
			return NINF;
		}
		z = x / sigma;

		return ln( erf( z * INV_SQRT_TWO ) );
	}
}


// EXPORTS //

module.exports = factory;
